db:delete.db:input-parameters:
#[%dw 2.0
output application/java
---
{
  id: attributes.uriParams.'orderId' default attributes.uriParams.'id'
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
if (payload > 0)
  {
	"message": "Order delete successfully from storage.",
	"status": "Success"
  }
else
  {
    "message": "No order was found with the provided ID.",
    "status": "Fail"
  }

%dw 2.0
output application/json
---
{
  "success": false,
  "correlationId": vars.correlationId,
  "error": {
    "code": "INTERNAL_SERVER_ERROR",
    "message": "Error processing the request in the database system.",
    "description": error.description default "No technical details available",
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
  }
}
